+template<typename SrcExp>
+struct ReduceWithAxisSrcTraits {
+  static const bool kUnitStrideF32 = false;
+  MSHADOW_XINLINE static const float *Lhs(const SrcExp &) { return NULL; }
+  MSHADOW_XINLINE static const float *Rhs(const SrcExp &) { return NULL; }
+  MSHADOW_XINLINE static index_t LhsStride(const SrcExp &) { return 0; }
+  MSHADOW_XINLINE static index_t RhsStride(const SrcExp &) { return 0; }
+};
+
+/*!
+ * \brief specialization for `tensor * tensor` over cpu 3D float, the only
+ *  shape whose source elements are directly addressable.
