+  typedef BinaryMapExp<op::mul, Tensor<cpu, 3, float>, Tensor<cpu, 3, float>,
+                       float, etype> SrcT;
+  static const bool kUnitStrideF32 = true;
+  MSHADOW_XINLINE static const float *Lhs(const SrcT &e) { return e.lhs_.dptr_; }
+  MSHADOW_XINLINE static const float *Rhs(const SrcT &e) { return e.rhs_.dptr_; }
+  MSHADOW_XINLINE static index_t LhsStride(const SrcT &e) { return e.lhs_.stride_; }
+  MSHADOW_XINLINE static index_t RhsStride(const SrcT &e) { return e.rhs_.stride_; }
+};
