+/*!
+ * \brief RVV unit-stride sum-of-products for float32.
+ *  Two independent vector accumulators shorten the loop-carried FP dependency
+ *  chain; the horizontal combine is a single vfredusum seeded with zero.
+ *  Returns false when the vector path is not applicable so that the caller
+ *  falls back to the scalar path.  Note: vfredusum is unordered, so callers
+ *  relying on the strict scalar addition order must validate the tolerance.
+ */
+template<typename DType>
+struct ReduceWithAxisRvv {
+  MSHADOW_XINLINE static bool Run(const float *, const float *, index_t, DType *) {
+    return false;
+  }
+};
+
+template<>
+struct ReduceWithAxisRvv<float> {
+  MSHADOW_XINLINE static bool Run(const float *lhs, const float *rhs,
+                                  index_t n, float *out) {
+    if (lhs == NULL || rhs == NULL || n <= 0) return false;
+    const size_t len = static_cast<size_t>(n);
+    const size_t vlmax = __riscv_vsetvl_e32m2(len);
+    vfloat32m2_t acc0 = __riscv_vfmv_v_f_f32m2(0.0f, vlmax);
+    vfloat32m2_t acc1 = __riscv_vfmv_v_f_f32m2(0.0f, vlmax);
+    size_t k = 0;
+    while (k + 2 * vlmax <= len) {
+      vfloat32m2_t a0 = __riscv_vle32_v_f32m2(lhs + k, vlmax);
+      vfloat32m2_t b0 = __riscv_vle32_v_f32m2(rhs + k, vlmax);
+      vfloat32m2_t a1 = __riscv_vle32_v_f32m2(lhs + k + vlmax, vlmax);
+      vfloat32m2_t b1 = __riscv_vle32_v_f32m2(rhs + k + vlmax, vlmax);
+      acc0 = __riscv_vfmacc_vv_f32m2(acc0, a0, b0, vlmax);
+      acc1 = __riscv_vfmacc_vv_f32m2(acc1, a1, b1, vlmax);
+      k += 2 * vlmax;
+    }
+    while (k < len) {
+      const size_t vl = __riscv_vsetvl_e32m2(len - k);
+      vfloat32m2_t a = __riscv_vle32_v_f32m2(lhs + k, vl);
+      vfloat32m2_t b = __riscv_vle32_v_f32m2(rhs + k, vl);
+      acc0 = __riscv_vfmacc_vv_f32m2(acc0, a, b, vl);
+      k += vl;
+    }
+    vfloat32m2_t vsum = __riscv_vfadd_vv_f32m2(acc0, acc1, vlmax);
+    vfloat32m1_t seed = __riscv_vfmv_s_f_f32m1(0.0f, vlmax);
+    vfloat32m1_t red = __riscv_vfredusum_vs_f32m2_f32m1(vsum, seed, vlmax);
+    *out = __riscv_vfmv_f_s_f32m1_f32(red);
+    return true;
+  }
+};
+#endif  // defined(__riscv) && defined(__riscv_v)
